L[", minutes left"] = "，剩余分钟"
L[", next in %dm"] = "，%d分钟后下一次"
L[", on screen"] = "，屏幕上"
L[", passive"] = "，被动"
L[", plays a sound"] = "，播放音效"
L[", preset saved"] = "，预设已保存"
L[", reported to chat"] = "，通报到聊天"
L[", sharing is off"] = "，共享已关闭"
L[", shown at max level"] = "，满级时显示"
L[", speaks"] = "，语音播报"
L[", tracker "] = "，追踪 "
L[", trail"] = "，拖尾"
L[", upgrades on tooltips"] = "，鼠标提示中显示提升"
L[", vendors and trainers in cities only"] = "，仅显示城市中的商人和训练师"
L[", vertical"] = "，竖向"
L[", wearing "] = "，穿着 "
L[", with debuffs"] = "，含减益效果"
L[", with you"] = "，在你身边"
L["-Combat"] = "-战斗"
L[". Ctrl+C to copy it, then send it in a support request on Discord to be added."] = "。按 Ctrl+C 复制，然后在 Discord 上提交支持请求，以便将其加入。"
L[". Ctrl+C to copy it, then send it to the team on Discord to be added."] = "。按 Ctrl+C 复制，然后在 Discord 上发给团队，以便将其加入。"
L[". Make first: "] = "。先制造："
L[". Open the mailbox on those characters to keep it."] = "。在这些角色上打开邮箱即可保留。"
L[". Unlock its window to drag and resize it, or place it in the HUD Editor."] = "。解锁其窗口即可拖动并调整大小，也可以在HUD编辑器中摆放。"
L["... and %d more"] = "……以及另外 %d 个"
L["/copy puts the text of whatever is under your cursor in a box you can copy from. /copy followed by a frame name copies that frame's text instead."] = "/copy 会把鼠标指针下内容的文本放进一个可复制的文本框。/copy 后接框体名称则复制该框体的文本。"
L["/nf ab <name>: imports a saved action bar set; /nf ab lists them"] = "/nf ab <名称>：导入已保存的动作条方案；/nf ab 列出全部"
L["/nf badges id: your badge claim code"] = "/nf badges id：你的徽章领取码"
L["/nf bars save, restore, test or delete <name>: your action bar sets; /nf bars list lists them"] = "/nf bars save、restore、test 或 delete <名称>：管理你的动作条方案；/nf bars list 列出全部"
L["/nf lockouts: your raid and dungeon lockouts"] = "/nf lockouts：你的团队和地下城锁定"
L["/nf move (or /nf hud): opens or closes the HUD Editor"] = "/nf move（或 /nf hud）：打开或关闭HUD编辑器"
L["/nf quiz: the WoW quiz"] = "/nf quiz：魔兽世界知识问答"
L["/nf ranks: higher ranks to put on your bars"] = "/nf ranks：可放到动作条上的更高等级法术"
L["/nf junk: the Junk List"] = "/nf junk：垃圾列表"
L["/nf trainer: a waypoint to your nearest class trainer"] = "/nf trainer：设置前往最近职业训练师的路径点"
L["/nf xp start, pause or reset: the XP ticker"] = "/nf xp start、pause 或 reset：经验值计时器"
L["/nf: opens the settings"] = "/nf：打开设置"
L["/nfquests (or /nfcompleto): the Quest List, in Discovery"] = "/nfquests（或 /nfcompleto）：探索中的任务列表"
L["0 keeps it up until you close it."] = "0 表示一直显示，直到你关闭它。"
L["1 %s is worth %g to %s."] = "对 %3$s 而言，1 %1$s 价值 %2$g。"
L["1 book"] = "1 本书"
L["1 consumable"] = "1 种消耗品"
L["1 consumable watched"] = "监视 1 种消耗品"
L["1 craft"] = "1 次制造"
L["1 day"] = "1 天"
L["1 dungeon"] = "1 个地下城"
L["1 hour"] = "1 小时"
L["1 in %d"] = "1/%d"
L["1 item on the bar"] = "条上有 1 件物品"
L["1 minute"] = "1 分钟"
L["1 paladin in your group"] = "队伍中有 1 名圣骑士"
L["1 player has their own blessing"] = "1 名玩家有自己指定的祝福"
L["1 profile on this account"] = "此账号上有 1 个配置文件"
L["1 raid"] = "1 个团队副本"
L["1 runs Naowh Forever"] = "1 人在使用 Naowh Forever"
L["1 setting changed from its default"] = "1 项设置已更改默认值"
L["1 spell"] = "1 个法术"
L["1 Unspent Talent Point"] = "1 点未分配的天赋点数"
L["1. PICK YOUR BARS"] = "1. 选择动作条"
L["100%  (default)"] = "100%  （默认）"
L["100%, native resolution"] = "100%，原生分辨率"
L["12-hour clock"] = "12小时制"
L["16x Anisotropic"] = "16倍各向异性"
L["2. ALSO KEEP"] = "2. 同时保留"
L["24-Hour Clock"] = "24小时制"
L["24-hour clock"] = "24小时制"
L["3. NAME AND SAVE"] = "3. 命名并保存"
L["30, while the game is not in focus"] = "30，游戏窗口不在前台时"
L[": copy ID or Wowhead link"] = "：复制 ID 或 Wowhead 链接"
L[": mail expiring soon on "] = "：邮件即将过期，角色："
L["; buys at vendors"] = "；向商人购买"
L["<AFK>"] = "<暂离>"
L["<DND>"] = "<忙碌>"
L["[Where?]"] = "[在哪？]"
L["A /thank to everyone around you when the game cannot name the caster."] = "游戏无法识别施法者时，向周围所有人发送 /thank。"
L["A [Where?] link after a whisper from someone whose zone is not known. Clicking it runs a /who for them and prints their zone; their next messages are tagged."] = "收到所在区域未知的玩家密语后显示 [在哪？] 链接。点击会对其执行 /who 并显示其所在区域；之后的消息会附上区域标记。"
L["A banner and a sound when one of them joins your group."] = "其中有人加入你的队伍时显示横幅并播放音效。"
L["A bar at the threat where you would pull aggro, so the gap to it is easy to read."] = "在你会获得仇恨的威胁值处显示一条线，便于看清差距。"
L["A bar for your target's swings, restarted by each physical hit you take while it is targeting you, and shortened when it parries. It is an estimate: the game does not say who hit you or with what, so other attackers, physical specials and bleed ticks restart it too."] = "显示目标平砍的计时条，目标以你为目标时，你每次受到物理攻击都会重置，目标招架时会缩短。这只是估算：游戏不会告知是谁用什么攻击了你，因此其他攻击者、物理技能和流血伤害也会重置它。"
L["A bar left out is not touched by an import."] = "未选择的动作条不会受导入影响。"
L["A bar per group member with their level and how far through it they are. Every member running Naowh Forever shares their experience, even with this off; anyone else shows their level. Updates wait until combat ends. Move it in the HUD Editor."] = "为每名队伍成员显示一条进度条，包含等级和当前等级进度。使用 Naowh Forever 的成员即使关闭此项也会共享经验值；其他人只显示等级。战斗结束后才会更新。可在HUD编辑器中移动。"
L["A bar with the name, a turn arrow and the distance, while a waypoint is set."] = "设置路径点时，显示一条包含名称、转向箭头和距离的信息条。"
L["A batch of ten, four done, as it shows while you craft."] = "制造中显示的样子：一批十个，已完成四个。"
L["A black outline round the clock."] = "为时钟添加黑色描边。"
L["A black outline round the FPS / MS readout and the counts, in place of the soft shadow."] = "为 FPS / MS 读数和计数添加黑色描边，取代柔和阴影。"
L["A black outline round the text, in place of the soft shadow."] = "为文字添加黑色描边，取代柔和阴影。"
L["A button per set: click to equip, Shift-click to save what you wear into it, Ctrl-click to rename it, right-click to change its icon, and + to save a new one. The set you wear is outlined. Move it in the HUD Editor."] = "每个方案一个按钮：点击装备，Shift+点击将当前穿着保存到该方案，Ctrl+点击重命名，右键点击更换图标，点击 + 保存新方案。当前穿着的方案会带有轮廓。可在HUD编辑器中移动。"
L["A button that flags or unflags you for PvP, showing which you are."] = "一个开启或关闭PvP状态的按钮，并显示当前状态。"
L["A campfire in range and Camp Benefits about to run out."] = "营火在范围内，且露营增益即将结束。"
L["A campfire in range and no Camp Benefits."] = "营火在范围内，但没有露营增益。"
L["A campfire is in range"] = "营火在范围内"
L["A card behind the text, a soft dark fade, or nothing at all."] = "文字后方的卡片、柔和的暗色渐隐，或什么都不显示。"
L["A card over the pin with what it is and how far."] = "在标记上方显示卡片，说明其内容和距离。"
L["A cast part way through, swept around the ring."] = "施法进行到一半，沿光圈转动显示。"
L["A cast someone interrupted, held for the fade time."] = "被他人打断的施法，在淡出时间内保持显示。"
L["A cast while your interrupt is on cooldown, with the tick where it comes back."] = "你的打断技能冷却中时的施法，并标出其冷却结束的位置。"
L["A cast while your interrupt is ready."] = "你的打断技能就绪时的施法。"
L["A cast you cannot interrupt, with its shield."] = "无法打断的施法，带有盾牌标识。"
L["A character shows up here after you log into it with Instance Tracker on. Track Alts shows the others: rested experience and durability, from the last time that character was logged in."] = "开启副本统计后登录的角色会显示在这里。追踪小号会显示其他角色：其休息经验和耐久度，取自该角色上次登录时。"
L["A choice among its rewards: pick this one."] = "可在其奖励中选择：选这一件。"
L["A command name can only use letters, numbers and underscores."] = "命令名称只能包含字母、数字和下划线。"
L["A consumable or personal buff with less time than this left counts as missing."] = "剩余时间少于此值的消耗品或个人增益视为缺失。"
L["A crosshair at the middle of your screen."] = "在屏幕中央显示十字准星。"
L["A cup beside a healer who is drinking."] = "治疗者正在喝水时在其旁边显示杯子图标。"
L["A custom command can't reload. Type /reload."] = "自定义命令无法重载界面。请输入 /reload。"
L["A dark or light fill and edge behind each line, or none."] = "每行后方的深色或浅色填充和边缘，或不显示。"
L["A dark panel behind the icons."] = "图标后方的深色面板。"
L["A door on each dungeon and raid entrance on the world map, for the sides the Journal lists. Hover it for the levels, click it for a waypoint."] = "在世界地图上每个地下城和团队副本入口处（按地下城手册所列）显示一扇门。悬停查看等级，点击设置路径点。"
L["A dot on a slot where a better enchant for your level waits: hover it for the advice, click it to ask in Trade."] = "在有更适合你等级的附魔的栏位上显示圆点：悬停查看建议，点击在交易频道询问。"
L["A fading trail behind the cursor."] = "鼠标指针后方渐隐的拖尾。"
L["A few quick steps for %s only, its own modules included."] = "仅针对 %s 的几个快速步骤，包括其自带模块。"
L["A game that opens when a flight starts and closes when you land."] = "飞行开始时打开、降落时关闭的小游戏。"
L["A game to pass the flight: the Quiz or the Aim Trainer. It closes when you land."] = "飞行途中消磨时间的小游戏：知识问答或瞄准训练。降落时关闭。"
L["A gear set called %s already exists."] = "名为 %s 的装备方案已存在。"
L["A glow on the moving edge of the fill."] = "在填充的移动边缘显示光晕。"
L["A hidden quest chain across Azeroth: click each thing in the world in turn. It gives a lot of experience, and ends in the Cozy Sleeping Bag; rest in it for a bonus to experience."] = "一条遍布艾泽拉斯的隐藏任务线：依次点击世界中的每个物体。它能提供大量经验值，最终奖励舒适的睡袋；在睡袋中休息可获得经验值加成。"
L["A key that opens Group Inspect."] = "打开队伍观察的按键。"
L["A key that shows a boss's loot at your cursor."] = "在鼠标指针处显示首领掉落的按键。"
L["A key that uses this item."] = "使用此物品的按键。"
L["A later point needs it. "] = "后续的点需要它。"
L["A later step."] = "后续步骤。"
L["A line for each quest you turn in, with the experience and money it gave. Reward items show as their own lines."] = "每上交一个任务显示一行，包含获得的经验值和金钱。奖励物品单独成行。"
L["A line for every reputation gain, from quests and kills alike."] = "每次获得声望显示一行，任务和击杀均包括在内。"
L["A line for the experience from each kill. Quest experience is on the quest's own line."] = "每次击杀获得的经验值显示一行。任务经验值显示在任务自己的行中。"
L["A line from the pin down to a map pin's or corpse's spot."] = "从标记向下连到地图标记或尸体位置的线。"
L["A line in chat with the item's link."] = "在聊天中显示一行物品链接。"
L["A line in their color on their player tooltip."] = "在其玩家鼠标提示中以其颜色显示一行。"
L["A line to share them with."] = "用于分享的一行文本。"
L["A line under the ID saying which keys copy it (Ctrl-Shift-C: copy ID or Wowhead link). Off, the shortcut still works; the line is just not shown."] = "在 ID 下方显示一行，说明复制它的按键（Ctrl-Shift-C：复制 ID 或 Wowhead 链接）。关闭后快捷键依然有效，只是不显示这一行。"
L["A look you do not have yet|r"] = "你尚未拥有的外观|r"
L["a macro made on this character"] = "在此角色上创建的宏"
L["A macro this character does not have yet: the import makes it."] = "此角色尚未拥有的宏：导入时会创建它。"
L["A minimap button that opens %s. /nf%s does the same, and the Top Bar can carry it too. Saved for this computer."] = "打开 %s 的小地图按钮。/nf%s 效果相同，顶部信息条也可以放置它。按此电脑保存。"
L["A Naowh weights line, or a WoWSims EP export (in WoWSims: Stat Weights, Copy to Current EP, Export)"] = "Naowh 权重文本，或 WoWSims EP 导出（在 WoWSims 中：Stat Weights、Copy to Current EP、Export）"
L["A Naowh weights line, or a WoWSims EP export."] = "Naowh 权重文本，或 WoWSims EP 导出。"
L["A new session, before any experience."] = "新的统计时段，尚未获得经验值。"
L["A parry by your target took 40% off its swing."] = "目标的一次招架使其平砍时间缩短了40%。"
L["A party of five, a card each."] = "五人小队，每人一张卡片。"
L["A player's score on their tooltip. One running Naowh Forever shares theirs; anyone else's is read from their gear when you hover them, within inspect range and out of combat."] = "在玩家的鼠标提示中显示其评分。使用 Naowh Forever 的玩家会共享评分；其他玩家的评分在你悬停时根据其装备读取，需在观察范围内且不在战斗中。"
L["A profile"] = "一个配置文件"
L["a quest"] = "一个任务"
L["A quest reward for the other faction; try the Auction House."] = "这是另一阵营的任务奖励；可以去拍卖行看看。"
L["A raid for %d players"] = "%d 人团队副本"
L["A raid, a row each."] = "一个团队，每人一行。"
L["A rare someone else is fighting."] = "其他人正在战斗的稀有怪物。"
L["A rare you have killed before."] = "你击杀过的稀有怪物。"
L["A rare you have not killed yet."] = "你尚未击杀的稀有怪物。"
L["A reward from the quest "] = "任务奖励："
L["A ring around your cursor so you never lose it in a busy fight, with your global cooldown and casts swept around it."] = "在鼠标指针周围显示光圈，让你在混乱的战斗中不会丢失指针，并沿光圈显示公共冷却和施法进度。"
L["A round in progress."] = "一局进行中。"
L["A row of icons for missing food, flask, elixir and scroll buffs, your own class buff, and class buffs missing in your group. Out of combat only: the game keeps your buffs from addons in combat, so the icons keep what they showed. Hover one to pick a carried item to use. Move them in the HUD Editor."] = "一排图标，显示缺失的食物、合剂、药剂和卷轴增益、你自己的职业增益，以及队伍中缺失的职业增益。仅在非战斗中更新：战斗中游戏不允许插件读取你的增益，因此图标保持原样。悬停在图标上可选择要使用的携带物品。可在HUD编辑器中移动。"
L["A running gold per hour beside the newest line, counting money and item value since your first loot this session."] = "在最新一行旁显示实时每小时金币，统计本次登录首次拾取以来的金钱和物品价值。"
L["A Scan Prices button on the auction house. It reads every listing and keeps the lowest buyout for each item, for this realm and faction. Blizzard allows one full scan every 15 minutes."] = "在拍卖行添加扫描价格按钮。它会读取所有拍卖并记录每件物品的最低一口价，按服务器和阵营区分。暴雪每15分钟只允许一次完整扫描。"
L["A junk icon on the bag slot of each item marked as junk."] = "在每件标记为垃圾的物品所在背包格上显示垃圾图标。"
L["A second panel for your focus, to keep Sap or Polymorph's time on one enemy while you fight another."] = "为焦点目标显示第二个面板，以便在攻击其他敌人时关注某个敌人身上闷棍或变形术的剩余时间。"
L["A set that goes on by itself while you ride or rest, and the set you had on goes back afterwards."] = "骑乘或休息时自动换上的装备方案，之后会换回原来的方案。"
L["A shooting game for flights: click the other faction's races as fast as you can."] = "飞行途中的射击小游戏：尽快点击另一阵营的种族。"
L["A short flash of text entering and leaving combat. Move it in the HUD Editor."] = "进入和离开战斗时短暂闪现文字。可在HUD编辑器中移动。"
L["A small bar with your next trainer visit and your gold, to leave up while you level. Move it by dragging."] = "显示下次训练师拜访和你的金币的小信息条，可在升级时常驻显示。拖动即可移动。"
L["A small health bar for the other tank in your group, shown while you are tanking: tank role, Bear Form, Defensive Stance or Righteous Fury. The other tank is whoever has the tank role or the raid's Main Tank assignment. Click it to target them. Changes made in combat apply when the fight ends. Move it in the HUD Editor."] = "你在坦克时为队伍中另一名坦克显示一条小生命条：坦克职责、熊形态、防御姿态或正义之怒。另一名坦克指拥有坦克职责或被指定为团队主坦克的人。点击即可选中对方。战斗中所做的更改在战斗结束后生效。可在HUD编辑器中移动。"
L["A soft glow around Naowh's arrow."] = "Naowh 箭头周围的柔和光晕。"
L["A soft glow beside each icon."] = "每个图标旁的柔和光晕。"
L["A soft glow round it in your accent color."] = "以你的强调色在其周围显示柔和光晕。"
L["A soft glow round it in your rank's color."] = "以你的等级颜色在其周围显示柔和光晕。"
L["A soft ring pulses around each target."] = "每个目标周围有柔和的光圈脉动。"
L["a sound to refresh"] = "刷新提示音效"
L["A sound, or the Speech text read aloud, as each cast starts."] = "每次施法开始时播放音效或朗读语音文本。"
L["A sound, or the Speech text read aloud. Text to Speech can stutter on some PCs, as the game waits while Windows speaks it; a Sound costs nothing."] = "播放音效或朗读语音文本。文字转语音在某些电脑上可能导致卡顿，因为游戏会等待 Windows 朗读完毕；音效则没有任何开销。"
L["A spell an import could not place because you do not know it yet goes into its saved slot when you learn it, unless you have put something else there."] = "导入时因尚未学会而无法放置的法术，会在你学会后放入保存的栏位，除非你已在该处放了其他东西。"
L["A Stack button on the card when part-filled stacks of an item can be combined."] = "当某物品的未满堆叠可以合并时，在卡片上显示堆叠按钮。"
L["A star on the world map for every rare you have not killed, where it is most likely to be. Hover one for the rare and its drops, its other spawn spots and, if it patrols, its way; click it for a waypoint, right-click it to keep its spots and way shown."] = "在世界地图上为每个你尚未击杀的稀有怪物在其最可能出现的位置显示星标。悬停查看稀有怪物及其掉落、其他刷新点，以及巡逻路线（如有）；点击设置路径点，右键点击保持显示其刷新点和路线。"
L["A string to share it with."] = "用于分享的字符串。"
L["A supporter"] = "支持者"
L["A team member"] = "团队成员"
L["A text on the bar: click it on the preview to change it. Each text shows in one place on the bar: picking one shown elsewhere moves it there."] = "条上的文字：在预览中点击即可更改。每种文字只在条上一个位置显示：选择已在其他位置显示的文字会将其移到此处。"
L["A tick on the bar where your interrupt comes off cooldown. Hidden while it is ready."] = "在条上标出打断技能冷却结束的位置。技能就绪时隐藏。"
L["A title bar naming the mob the threat is on."] = "显示威胁值所针对怪物名称的标题栏。"
L["A trained spell drops into its saved slot."] = "训练的法术会放入其保存的栏位。"
L["a vendor sells the formula"] = "商人出售该配方"
L["A warning when a rare is near"] = "稀有怪物靠近时警告"
L["A warning when a rare is near you: when its nameplate comes up, you mouse over it or target it. A card with its portrait: right-click it to close it, and its pin sets a waypoint to the rare. Move it in the HUD Editor."] = "稀有怪物靠近时发出警告：其姓名板出现、你鼠标指向或选中它时。显示一张带头像的卡片：右键点击关闭，点击其标记可设置前往该稀有怪物的路径点。可在HUD编辑器中移动。"
L["A warning while a hunter or warlock has no pet out. A warlock who sacrificed their demon is left alone. Move it in the HUD Editor."] = "猎人或术士没有召唤宠物时发出警告。已牺牲恶魔的术士不受影响。可在HUD编辑器中移动。"
L["A word of your own on the icon."] = "在图标上显示你自定义的文字。"
L["A world drop from %d kinds of mob"] = "世界掉落，来自 %d 种怪物"
L["A WoW quiz for campfires and flights, or any time with /naowh quiz."] = "在营火旁和飞行途中玩的魔兽世界知识问答，也可随时用 /naowh quiz 打开。"
L["A yellow ! on the world map at every quest giver with a quest you can pick up that still gives experience. Hover it for the quests; click it for a waypoint."] = "在世界地图上每个有可接且仍能提供经验值任务的任务发布者处显示黄色感叹号。悬停查看任务，点击设置路径点。"
L["A zone older than this is no longer shown, since the player has likely moved on."] = "早于此时间的区域信息将不再显示，因为该玩家很可能已经离开。"
L["Abandon %s?"] = "放弃 %s？"
L["Abilities"] = "技能"
L["about "] = "约 "
L["about %d:%02d"] = "约 %d:%02d"
L["About %s at your last scan%s%s"] = "上次扫描时约为 %s%s%s"
L["About %s spent"] = "约花费 %s"
L["About a minute."] = "约一分钟。"
L["Above"] = "上方"
L["Acc."] = "精准"
L["Accent: missing the class blessing. Lighter: running out. Deeper: only players with their own."] = "强调色：缺少职业祝福。较浅：即将结束。较深：仅缺少有自己指定祝福的玩家。"
L["Accept Quests"] = "接受任务"
L["Accept Shared Dungeon Quests"] = "接受共享的地下城任务"
L["Accepts a quest as soon as its text opens. Use the Modifier to read it first."] = "任务文本一打开就接受任务。使用修饰键可以先阅读。"
L["Accepts dungeon quests your group shares with you straight away."] = "立即接受队伍共享给你的地下城任务。"
L["Accepts shared quests"] = "接受共享任务"
L["Accepts the popup on screen: a summons, a resurrection, a group invite."] = "接受屏幕上的弹窗：召唤、复活、组队邀请。"
L["Accepts, hands in and shares quests for you, and remembers the reward you saved for a quest. The Modifier skips them or triggers them, as Modifier Does says."] = "自动为你接受、上交和共享任务，并记住你为任务保存的奖励选择。修饰键会跳过或触发这些操作，具体取决于“修饰键作用”的设置。"
