L["Activity Bar Height"] = "活动条高度"
L["Add %d item to your junk list: %s%s?"] = "将 %d 件物品添加到你的垃圾列表：%s%s？"
L["Add %d items to your junk list: %s%s?"] = "将 %d 件物品添加到你的垃圾列表：%s%s？"
L["Add %d macro as character macros?%s"] = "将 %d 个宏添加为角色专用宏？%s"
L["Add %d macros as character macros?%s"] = "将 %d 个宏添加为角色专用宏？%s"
L["Add %s"] = "添加 %s"
L["Add %s (%d items) as a new BiS list?"] = "将 %s（%d 件物品）添加为新的BiS列表？"
L["Add %s to the Consumable Bar?"] = "将 %s 添加到消耗品条？"
L["Add a backup pick"] = "添加备选"
L["Add a Button"] = "添加按钮"
L["Add a stat"] = "添加属性"
L["Add an item ID, or import a list. Food counts any Well Fed buff and other items their own buff; add buff spell IDs only for an item that gives another. Nothing is added automatically. Hover a reminder to choose a configured item from your bags. Reminders pause in combat; item menus work outside combat. When and where they show is on AuraBuffs > Settings."] = "添加物品 ID，或导入列表。食物以任意进食充分增益为准，其他物品以其自身增益为准；只有当物品提供其他增益时才需添加增益法术 ID。不会自动添加任何内容。悬停在提醒上可从背包中选择已配置的物品。提醒在战斗中暂停；物品菜单在非战斗中可用。显示的时机和位置在 AuraBuffs > 设置 中设定。"
L["Add consumables, put them in order, and set each one up."] = "添加消耗品，排好顺序，并逐一设置。"
L["Add Items"] = "添加物品"
L["Add Latency"] = "加入延迟"
L["Add macros someone shared with you."] = "添加他人与你分享的宏。"
L["Add or remove your commands, turn each one on or off, or restore the defaults."] = "添加或移除你的命令，逐一开启或关闭，或恢复默认。"
L["Add Slash Command"] = "添加斜杠命令"
L["Add the %s build %s (%d points)?"] = "添加%s天赋方案 %s（%d 点）？"
L["Add the consumables to watch in the AuraBuffs window."] = "在 AuraBuffs 窗口中添加要监视的消耗品。"
L["Add Themes to RestedXP"] = "为 RestedXP 添加主题"
L["Add to BiS List"] = "加入BiS列表"
L["Add to Shopping List"] = "加入购物清单"
L["Add to the Left Side"] = "添加到左侧"
L["Add to the Right Side"] = "添加到右侧"
L["Add your consumables, put them in order, set each one up."] = "添加你的消耗品，排好顺序，逐一设置。"
L["Add your own lines to the bag macros. They are kept after the item, whatever is in your bags."] = "在背包宏中添加你自己的行。无论背包中有什么，它们都会保留在物品之后。"
L["Added %d consumable to the Consumable Bar."] = "已将 %d 种消耗品添加到消耗品条。"
L["Added %d consumables to the Consumable Bar."] = "已将 %d 种消耗品添加到消耗品条。"
L["Added %d consumables; %d were already listed or past the %d limit."] = "已添加 %d 种消耗品；%d 种已在列表中或超出 %d 个的上限。"
L["Added %d of %d: %s."] = "已添加 %d/%d：%s。"
L["Added %d."] = "已添加 %d 个。"
L["Added %s to this character. Drag it to a bar from the game's macro window (/macro)."] = "已将 %s 添加到此角色。请从游戏的宏窗口（/macro）将其拖到动作条上。"
L["Added %s to your BiS %s as #%d."] = "已将 %s 添加到你的BiS %s，排第 %d 位。"
L["Added %s to your BiS %s."] = "已将 %s 添加到你的BiS %s。"
L["Added next to your Library, never over it"] = "添加到你的宏库旁，不会覆盖它"
L["Added next to your own lists, never over them"] = "添加到你自己的列表旁，不会覆盖它们"
L["Added next to your saved builds"] = "添加到你已保存的天赋方案旁"
L["Adding Items"] = "添加物品"
L["Addon Font"] = "插件字体"
L["Addon List"] = "插件列表"
L["Addon Memory"] = "插件内存"
L["Adds \"- [1] + Add to List\" under a recipe's reagents: the materials Buy on AH would buy for that many crafts go on a shopping list, from anywhere. At the auction house the list shows beside it: Check Prices looks each one up and warns in red when one is well above your last scan, then Buy All goes through the list one material at a time, each bought only when you confirm its final price. A material you can make for less from its parts, such as a bar from ore, has its parts bought instead."] = "在配方材料下方添加\"- [1] + 加入清单\"：在任何地方都可把拍卖行购买为该数量制造所需购买的材料加入购物清单。在拍卖行时，清单显示在旁边：检查价格会逐一查询，若某项远高于你上次扫描的价格则以红色警告；然后全部购买会逐个材料处理清单，每项都需你确认最终价格后才购买。可以用原料更便宜地制造的材料（例如用矿石熔炼的锭）会改为购买其原料。"
L["Adds a Bags column to the chosen recipe's reagents, showing how many of each you carry."] = "在所选配方的材料中添加背包列，显示每种材料你携带的数量。"
L["Adds a Bank column to the chosen recipe's reagents, showing how many of each are in your bank."] = "在所选配方的材料中添加银行列，显示每种材料在你银行中的数量。"
L["Adds a button to the popup that swaps every lower rank on your bars for the highest rank you know. Keyboard and controller bars land in the same slot. Right-click a spell in the popup to keep its lower ranks, for downranking. Rank swaps only happen out of combat."] = "在弹窗中添加一个按钮，将动作条上所有低等级法术替换为你已学会的最高等级。键盘和手柄动作条会放入相同栏位。在弹窗中右键点击法术可保留其低等级，用于降级施法。等级替换只在非战斗中进行。"
L["Adds a Land button to come down at the next stop on the way."] = "添加降落按钮，在途中的下一站降落。"
L["Adds a line that flags any slot whose enchant is missing or differs from the ones you captured with Capture Current Enchants. Hover it for the details."] = "添加一行，标出附魔缺失或与你通过记录当前附魔所记录的附魔不同的栏位。悬停查看详情。"
L["Adds a mana spell's healing or damage per mana and per second to its tooltip."] = "在消耗法力值的法术的鼠标提示中添加每点法力值和每秒的治疗或伤害。"
L["Adds a second, orange number next to each recipe: how many you could make after buying the reagents vendors sell, such as Weak Flux or Coarse Thread. The recipe's reagents then say how many of each to buy."] = "在每个配方旁添加第二个橙色数字：购买商人出售的材料（例如弱效助熔剂或粗线）后你可制造的数量。配方材料随后会显示每种需购买的数量。"
L["Adds how long the visit lasted."] = "加入拜访持续的时长。"
L["Adds target and focus switching to the meter's title bar."] = "在统计的标题栏添加目标和焦点切换。"
L["Adds the average experience here."] = "加入此处的平均经验值。"
L["Adds the coins looted."] = "加入拾取的钱币。"
L["Adds the consumables in your bags that are not on the bar yet."] = "添加背包中尚未在条上的消耗品。"
L["Adds the deaths."] = "加入死亡次数。"
L["Adds the experience gained."] = "加入获得的经验值。"
L["Adds the materials for one more craft."] = "加入再制造一次所需的材料。"
L["Adds the Naowh themes to RestedXP's theme list."] = "将 Naowh 主题加入 RestedXP 的主题列表。"
L["Adds the reputation gained."] = "加入获得的声望。"
L["Adds the visits at this level."] = "加入此等级的拜访次数。"
L["Adds the visits until you level."] = "加入升级前的拜访次数。"
L["Adds your bonus healing or spell damage; off shows the spell's base numbers."] = "计入你的治疗加成或法术伤害；关闭则显示法术的基础数值。"
