L["Advanced Combat Logging"] = "高级战斗日志"
L["after "] = "之后 "
L["After each fight longer than 15 seconds, how long you spent neither casting nor on the global cooldown, in chat."] = "每场超过15秒的战斗结束后，在聊天中显示你既未施法也不处于公共冷却的时长。"
L["after the 5% cut"] = "扣除5%手续费后"
L["After visiting a trainer, a small window lists the abilities you just learned. Abilities from a tome or a quest show a moment after you learn them. Drag one from the window onto your bars."] = "拜访训练师后，一个小窗口会列出你刚学会的技能。通过书籍或任务学会的技能会在学会片刻后显示。可将技能从窗口拖到动作条上。"
