L["Also a grey ! for quests you can still pick up that no longer give experience."] = "对于仍可接取但不再提供经验值的任务，也显示灰色感叹号。"
L["Also a grey star on the map for the rares you have killed."] = "也在地图上为你已击杀的稀有怪物显示灰色星标。"
L["Also hidden for a few seconds after you dismount, while the pet comes back."] = "下坐骑后宠物返回的几秒钟内也隐藏。"
L["Also Import"] = "同时导入"
