L["Also keeps your last whispers and group chat lines with each player."] = "同时保留与每位玩家最近的密语和队伍聊天记录。"
L["Also opens the world map on the waypoint, so you see where it is. Out of combat only."] = "同时在路径点处打开世界地图，方便你查看位置。仅限非战斗中。"
L["Also prints the summary when you leave a raid."] = "离开团队时也输出总结。"
L["Also reminds you inside instances. Off by default: few have herbs or ore."] = "在副本中也提醒。默认关闭：很少有副本有草药或矿石。"
L["Also shows each recipe's profit at the right of its row in the list, green or red. Recipes whose profit is not known show none."] = "同时在列表中每个配方所在行的右侧以绿色或红色显示利润。利润未知的配方不显示。"
L["Also thanks players in your party or raid."] = "也感谢你小队或团队中的玩家。"
L["Also used inside dungeons and raids."] = "在地下城和团队副本中也使用。"
L["Also warns about rares you have killed before."] = "对你击杀过的稀有怪物也发出警告。"
L["Also warns while your pet is set to passive."] = "宠物设为被动时也发出警告。"
L["Also warns while your pet's health is under the threshold, in combat too."] = "宠物生命值低于阈值时也发出警告，战斗中同样有效。"
L["Also worth a look"] = "同样值得一看"
L["Alt"] = "Alt"
L["Alt + Shift"] = "Alt + Shift"
L["Alt Item Counts"] = "小号物品数量"
L["Alt-click a reward you can choose, in the quest log or at the quest giver, to save it for that quest in this profile; Alt-click it again to clear it. It is selected when you hand the quest in, and Hand In Quests takes it for you."] = "在任务日志或任务发布者处 Alt+点击可选奖励，即可在此配置文件中为该任务保存它；再次 Alt+点击可清除。上交任务时会自动选中它，上交任务功能会替你领取。"
L["Alt-click an item in your bags to mark it as junk, and sell it at the next vendor."] = "在背包中 Alt+点击物品将其标记为垃圾，并在下一个商人处出售。"
L["Alts Button on Mail"] = "邮箱小号按钮"
L["Always"] = "总是"
L["always"] = "总是"
L["Always Sharpen"] = "始终锐化"
L["Always Show"] = "始终显示"
L["always shown"] = "始终显示"
L["Always, only in combat, or only out of combat."] = "总是、仅战斗中，或仅非战斗中。"
L["Ammo"] = "弹药"
L["Ammo to Carry"] = "携带弹药量"
L["Ammunition"] = "弹药"
L["An \"Inventory is full\" error brings the row up for 20 seconds, even with more free slots than the threshold above."] = "出现\"物品栏已满\"错误时，即使空格数多于上方阈值，也会显示该行20秒。"
L["An alt that already has this macro, by name and text or text alone, uses its own."] = "已拥有此宏（名称和内容相同，或仅内容相同）的小号会使用自己的宏。"
L["An Alts button beside the mailbox's Send tab lists your characters on this realm and faction with their level and gold. Pick one to fill the To box."] = "在邮箱发送标签旁添加小号按钮，列出你在此服务器和阵营的角色及其等级和金币。选择一个即可填入收件人栏。"
L["An Attach button beside the mailbox's Send tab: attach every trade good, one type of trade good, or your unbound gear in one click."] = "在邮箱发送标签旁添加附加按钮：一键附加所有商业物品、某一类商业物品，或你未绑定的装备。"
L["An ID the game keeps hidden: Hide Line leaves it off the tooltip, Show Hidden shows the line with Hidden in place of the number."] = "游戏隐藏的 ID：隐藏行会将其从鼠标提示中省去，显示隐藏项会显示该行并以“隐藏”代替数字。"
L["An item worth more at the auction house than at a vendor is valued at its auction price, from your last Scan Prices or TradeSkillMaster."] = "在拍卖行比卖给商人更值钱的物品，按其拍卖价格计算，取自你上次扫描价格或 TradeSkillMaster。"
L["An on-next-swing attack queued on the melee bars."] = "近战条上已排队的下次攻击技能。"
L["Anchor it to a frame first"] = "请先将其锚定到框体"
L["Anchor Settings"] = "锚点设置"
L["Anchor the %s"] = "锚定%s"
