L["Drag the right edge for width. Wheel: text size (Shift: height). Click a bonus or the time to show or hide it. Right-click for more."] = "拖动右边缘调整宽度。滚轮：文字大小（Shift：高度）。点击加成或时间以显示或隐藏。右键点击查看更多。"
