L["Each dungeon or raid visit while Instance Tracker is on: how long you were inside, the coins you looted and the experience you gained. Reputation gained is listed under the visit. Coming back to the same group within the hour, before you reset it, continues that visit, and the time outside is not counted. Other characters stay saved, and show here when Track Alts is on. Repairs and vendor sales are not counted. Older visits drop off the end of the list."] = "副本统计开启期间的每次地下城或团队副本进入记录：停留时长、拾取的钱币和获得的经验值。获得的声望列在该记录下。在一小时内、重置副本前以同一队伍返回，会延续该次记录，在外面的时间不计入。其他角色的记录会保留，开启“追踪小号”后在此显示。修理和向商人出售不计入。较早的记录会从列表末尾移除。"
L["Each line fades out after %ss."] = "每行在%s秒后淡出。"
L["Each one is an account macro. Put it on a bar once and it keeps itself current: loot a better potion, conjure fresh food or pick up bandages and the macro is rewritten to use the best you carry.\n\nThe game does not let macros change mid-fight, so a change during combat waits until it ends."] = "每个都是账号通用宏。放到动作条上一次即可自动保持最新：拾取更好的药水、制造新的食物或捡到绷带时，宏会被改写为使用你身上最好的物品。\n\n游戏不允许在战斗中修改宏，因此战斗中的更改会等到战斗结束后进行。"
L["Each point of the trail in a color of its own."] = "拖尾的每个点使用各自的颜色。"
L["Each slot's item level, in its icon's corner."] = "在每个栏位图标的角落显示物品等级。"
