L["For paladins, a button per class in your group. Left-click blesses the next member of that class who needs it, missing first, skipping anyone dead or out of range. Right-click a class to choose its blessing or open its player list. Move it in the HUD Editor. The preview edits it: right-click a class for its blessing, click the aura to choose it, wheel for size and Shift-wheel for spacing, drag the gap after the aura, x hides a button and + brings it back."] = "圣骑士专用，队伍中每个职业一个按钮。左键点击会祝福该职业中下一个需要的成员，优先缺少祝福的，跳过已死亡或超出范围的人。右键点击职业可选择其祝福或打开其玩家列表。在HUD编辑器中移动它。预览可直接编辑：右键点击职业选择祝福，点击光环进行选择，滚轮调整大小，Shift+滚轮调整间距，拖动光环后的间隙，x 隐藏按钮，+ 将其恢复。"
L["For Skyborne characters: ley lines (Alliance, for Read Ley Line) or Elemental Convergences (Horde, for Skysight) pinned on the world map. The game does not mark them: the addon knows the ones players have found, and saves each new one you cast your racial on. Other races see no pins."] = "Skyborne角色专用：在世界地图上标出魔网（联盟，用于“阅读魔网”）或元素交汇处（部落，用于“天穹视界”）。游戏不会标记它们：插件知道玩家已发现的那些，并会保存你施放种族技能的每个新地点。其他种族看不到标记。"
L["For your class: imports this set once on a new character, at level 1 with no experience yet."] = "适用于你的职业：在新角色1级且尚无经验时导入一次此方案。"
L["For your level"] = "适合你的等级"
