L["Hides the pop-ups for achievements, loot won and the like."] = "隐藏成就、赢得的战利品等弹窗。"
L["Hides the red error text, like \"not ready yet\" and \"out of range\", and the voice line that comes with it."] = "隐藏红色错误文字，如“还没有准备好”和“超出范围”，以及随之播放的语音。"
L["Hides the whole bar while you are in combat."] = "战斗中隐藏整条。"
L["Hides the zone and subzone names that appear as you travel."] = "隐藏旅行时出现的区域和子区域名称。"
