L["How close a book has to be before it pings."] = "书籍距离多近时发出提示音。"
L["How early you can press your next spell before the current one finishes, in milliseconds. 100 to 400 suits most: lower is more responsive, higher is more forgiving of latency. Melee around your ping + 100, ranged around your ping + 150."] = "在当前法术结束前多早可以按下下一个法术，单位为毫秒。100到400适合大多数人：越低响应越快，越高越能容忍延迟。近战约为你的延迟+100，远程约为你的延迟+150。"
L["How far along an icon starts to fade, from 0% (at once) to 95% (at the very end)."] = "图标从何时开始淡出，从0%（立即）到95%（最末）。"
L["How far below your level gear has to be for Old Common Gear."] = "装备需低于你等级多少才算“过时的普通装备”。"
