L["How long it takes to get there at your speed."] = "以你的速度到达那里需要多久。"
L["How long the current fight has run, on screen while you fight. Move it in the HUD Editor."] = "当前战斗已持续的时间，战斗时显示在屏幕上。在HUD编辑器中移动它。"
L["How long the fight lasted, in chat when it ends."] = "战斗结束时在聊天中显示战斗持续时间。"
