L["Once you have scanned the auction house (Scan Prices), the chosen recipe shows what its reagents cost to buy and what the item sells for, and the profit after the 5% auction house cut. Each reagent is priced at its cheapest: a vendor's price once you have seen a vendor sell it, else the lowest buyout at your last scan. Uncheck a reagent you already have to leave it out of the cost, for every recipe that uses it. Hover the lines for the breakdown."] = "扫描拍卖行（扫描价格）后，所选配方会显示购买材料的成本、物品的售价，以及扣除5%拍卖行手续费后的利润。每种材料按最低价计算：见过商人出售后使用商人价格，否则使用上次扫描的最低一口价。取消勾选已有的材料，即可在所有使用它的配方中将其排除在成本之外。将鼠标悬停在各行上查看明细。"
L["One addon"] = "一个插件"
L["One bar per weapon, timed by the game's own swing event, so parry haste, swing resets and haste are always right. Move them in the HUD Editor."] = "每把武器一个计时条，根据游戏自身的攻击事件计时，因此招架加速、攻击重置和急速始终准确。可在HUD编辑器中移动。"
L["One Fewer"] = "减少一个"
L["One item per click: the game needs a click for every disenchant."] = "每次点击一件物品：游戏要求每次分解都需要点击。"
L["One More"] = "增加一个"
L["One number for a character's gear, on the item level scale: 26.4 means gear worth a set of level 26 epics. Your own is always on the BiS List's paperdoll."] = "以物品等级衡量角色装备的单一数值：26.4表示装备相当于一套26级史诗装备。你自己的数值始终显示在BiS列表的人物模型上。"
L["One whisper per line, picked at random; {buff} and {name} are filled in."] = "每行一条密语，随机选取；{buff}和{name}会被自动填入。"
L["Online"] = "在线"
