L["Opens another player's profession link in this window, to order crafts from them. Choose a recipe, set how many crafts, tick the materials you bring (or type how many), and Add to Order. The order on the right has a suggested tip per craft that you can change; Ask sends the crafter one message per craft with the amount, your materials and the tip: in party chat when they are in your party, else as a whisper. Prices and the tip need an auction house scan."] = "在此窗口中打开其他玩家的专业链接，向其订购制造。选择配方，设置制造次数，勾选你提供的材料（或输入数量），然后加入订单。右侧订单中有每次制造的建议小费，可以修改；询问会为每次制造向制造者发送一条消息，包含数量、你的材料和小费：对方在你的小队中时发送到小队聊天，否则以密语发送。价格和小费需要扫描拍卖行。"
