L["Puts a raid marker on your focus. Pressing the macro again on the same focus clears the marker."] = "为你的焦点目标设置团队标记。对同一焦点目标再次按下宏会清除标记。"
L["Puts back every setting this page has changed, to the value you had before."] = "将此页面更改的所有设置还原为之前的值。"
L["Puts back everything changed since the HUD Editor opened."] = "还原自HUD编辑器打开以来的所有更改。"
L["Puts back the last change. Ctrl + Z."] = "撤销上一次更改。Ctrl + Z。"
L["Puts both back where the game shows them."] = "将两者放回游戏默认显示的位置。"
L["Puts every weight of this spec back to the defaults. Asks first."] = "将此专精的所有权重恢复为默认值。会先确认。"
L["Puts food, drink and potions 10 or more levels below you, marked with a clock, first."] = "将比你低10级或更多的食物、饮料和药水（以时钟标记）放在最前。"
L["Puts the bar back on the screen."] = "将条放回屏幕上。"
L["Puts the bar's buttons back as they came: the Dungeon Journal and Discovery on the left, the BiS List and Training Planner on the right."] = "将条上的按钮恢复为初始状态：左侧为地下城手册和探索，右侧为BiS列表和训练规划。"
L["Puts the card back above the middle of the screen, where it starts."] = "将卡片放回屏幕中央上方的初始位置。"
L["Puts the cheapest item at the far end of the row instead of next to its anchor."] = "将最便宜的物品放在行的最远端，而不是锚点旁边。"
L["Puts the cheapest item on your cursor, to drop or sell."] = "将最便宜的物品放到鼠标上，以便丢弃或出售。"
L["Puts the count just past the icon's edge."] = "将数量显示在图标边缘外侧。"
L["Puts the key just past the icon's edge."] = "将按键显示在图标边缘外侧。"
L["Puts the materials for that many crafts on your shopping list: every checked reagent that vendors do not sell, whatever is in your bags. Uncheck a reagent to leave it out. At the auction house the list shows beside it, to check the prices and buy it all."] = "将该次数制造所需的材料加入购物清单：所有已勾选且商人不出售的材料，不论背包中是否已有。取消勾选可排除某材料。在拍卖行时清单会显示在旁边，方便查看价格并全部购买。"
L["Puts the popup back where it first showed."] = "将弹窗放回其首次显示的位置。"
L["Puts the quiz back where it first opened."] = "将问答放回其首次打开的位置。"
L["Puts the text just past the icon's edge."] = "将文字显示在图标边缘外侧。"
L["Puts this recipe on the order on the right, with the number of crafts and the materials you bring. Changes made here after adding it change the order too. Up to %d recipes per order."] = "将此配方加入右侧订单，包含制造次数和你提供的材料。添加后在此处所做的更改也会同步到订单。每个订单最多%d个配方。"
L["Puts this set on. In combat, it goes on when the fight ends."] = "穿上此方案。战斗中则在战斗结束后穿上。"
