L["Shown in a group"] = "在队伍中显示"
L["Shown in combat"] = "战斗中显示"
L["Shown in combat."] = "战斗中显示。"
L["Shown in dungeons and raids."] = "在地下城和团队副本中显示。"
L["Shown while you are in a group."] = "在队伍中时显示。"
L["Shown while you have a bow, gun, crossbow, wand or thrown weapon."] = "装备弓、枪、弩、魔杖或投掷武器时显示。"
L["Shown while you have a weapon in your off hand."] = "副手装备武器时显示。"
L["Shown with threat"] = "有威胁值时显示"
L["Shown: click to hide it."] = "已显示：点击隐藏。"
L["Shows a dungeon's bosses and loot beside the world map while you are inside."] = "在副本内时，于世界地图旁显示该地下城的首领和掉落。"
L["Shows a healing item's icon the moment your health drops below the threshold, in combat too: the game shows and hides it itself. Move it in the HUD Editor."] = "生命值低于阈值时立即显示治疗物品的图标，战斗中也会显示：由游戏自身控制显示和隐藏。可在HUD编辑器中移动。"
L["Shows a sample spell's tooltip with the line as your settings draw it."] = "显示示例法术的鼠标提示，其中的行按你的设置绘制。"
L["Shows a zone's level range when you hover it on the world map."] = "在世界地图上悬停区域时显示其等级范围。"
L["Shows an icon on screen while you know Find Herbs, Find Minerals or Find Fish but are tracking none of them. Click it to start tracking: left-click for the first, right-click for the second, middle-click for the third. Hover it to see which is which. Hidden in combat. Move it in the HUD Editor."] = "当你学会寻找草药、寻找矿物或寻找渔点但未追踪任何一项时，在屏幕上显示一个图标。点击开始追踪：左键点击第一个，右键点击第二个，中键点击第三个。悬停查看对应关系。战斗中隐藏。可在HUD编辑器中移动。"
L["Shows each Sleeping Bag step, with how to reach the next one and a waypoint."] = "显示睡袋的每个步骤，以及如何前往下一步和路径点。"
L["Shows every bonus again; click one on the preview to hide it."] = "再次显示所有加成；在预览中点击一个即可隐藏。"
L["Shows how many of each you carry."] = "显示每种物品的携带数量。"
L["Shows if you're ahead of or behind your other characters, and colors past levels by it."] = "显示你领先还是落后于你的其他角色，并据此为过去的等级着色。"
L["Shows it again a little before its effect runs out."] = "在效果结束前不久再次显示。"
L["Shows only part of the raid."] = "只显示团队的一部分。"
L["Shows or hides the list of every element."] = "显示或隐藏所有元素的列表。"
L["Shows the factions earned where you are beside the world map."] = "在世界地图旁显示当前所在地可获得的声望。"
L["Shows the key that uses each button."] = "显示使用每个按钮的按键。"
L["Shows the meter with sample bars where it sits on your screen, for ten seconds. Out of combat only."] = "在其屏幕位置以示例条显示统计，持续十秒。仅限战斗外。"
L["Shows the other tank's debuffs beside their health bar, in combat too: tank-buster stacks, boss debuffs and anything you can dispel."] = "在另一名坦克的生命条旁显示其减益，战斗中也会显示：坦克重击层数、首领减益以及任何你可以驱散的效果。"
L["Shows the parts of the world map you have not explored yet, darkened."] = "在世界地图上以暗色显示你尚未探索的区域。"
L["Shows the row only once your bags are this full. 0 shows it all the time."] = "仅在背包达到此占用程度时显示该行。0表示始终显示。"
L["Shows the Sleeping Bag steps still to do on your map; click one for a waypoint."] = "在地图上显示尚未完成的睡袋步骤；点击一个获取路径点。"
L["Shows the warning with its sound, about your target if you can attack it."] = "显示警告并播放音效，若你可以攻击你的目标，则针对你的目标。"
L["Shows this bonus on the bar: %s."] = "在条上显示此加成：%s。"
L["Shows this recipe's reagents in your objective tracker, with how many you have of each."] = "在任务目标追踪中显示此配方的材料，以及你每种材料的数量。"
L["Shows this visit's time, coins, and experience."] = "显示本次访问的时间、钱币和经验值。"
L["Shows up once you take the talent"] = "学会该天赋后显示"
L["Shows who Naowh, the developers, the moderators and our Legendary and Epic patrons are: a badge by their name in chat, a line on their tooltip and, if you want it, a banner when one of them joins your group."] = "显示谁是Naowh、开发者、管理员以及我们的传说和史诗赞助者：聊天中名字旁的徽章、鼠标提示中的一行，以及（可选）他们加入你的队伍时的横幅。"
L["Shows your BiS stars to players who inspect you with Naowh Forever."] = "向使用Naowh Forever观察你的玩家显示你的BiS星标。"
L["Shows your note and tag on a player's tooltip."] = "在玩家的鼠标提示上显示你的备注和标签。"
L["Shows your other characters' visits."] = "显示你其他角色的访问记录。"
