L["Takes everything the moment you loot, with Blizzard's loot window kept out of sight, so the feed is all you see. Works with or without the game's auto loot. Hold Shift while looting to get the window back. It also appears whenever something cannot be taken: a group roll, a locked item, or bags too full."] = "拾取时立即拿走所有物品，并隐藏暴雪的拾取窗口，只显示拾取信息。无论是否开启游戏的自动拾取都有效。拾取时按住 Shift 可重新显示窗口。当有物品无法拾取时（队伍掷骰、锁定的物品或背包已满），窗口也会出现。"
