L["The cheapest items in your bags as a row of icons, cheapest first. Ctrl-click an icon to delete it, or click it to sell it while a vendor is open. Middle-click to ignore an item. Move it in the HUD Editor."] = "以一排图标显示背包中最便宜的物品，最便宜的在前。Ctrl+点击图标可将其摧毁，商人界面打开时点击可出售。中键点击可忽略物品。可在HUD编辑器中移动。"
L["The class's name, or its class icon, which fits however small the buttons are."] = "职业名称或职业图标，图标在按钮再小时也放得下。"
L["The color of the line on the tooltip."] = "鼠标提示中该行的颜色。"
L["The Consumable Bar will ask about those items again."] = "消耗品条会再次询问这些物品。"
L["The consumables your reminders watch"] = "提醒所监视的消耗品"
L["The consumables your reminders watch."] = "提醒所监视的消耗品。"
L["The Cozy Sleeping Bag's hidden quest chain, step by step."] = "舒适的睡袋的隐藏任务链，逐步说明。"
L["The crowd control on your target; pick which in the Crowd Control card below."] = "你目标身上的控制效果；在下方的“控制效果”卡片中选择要显示哪些。"
