L["The cursor left still."] = "光标静止不动。"
L["The debuffs on your target you pick in the Debuffs card below, like Mortal Strike."] = "你在下方“减益”卡片中选择的目标身上的减益效果，例如致死打击。"
L["The default is %s."] = "默认值为%s。"
