L["The Dungeon Quest Tracker's window."] = "地下城任务追踪的窗口。"
L["The dungeons on whose ground the list shows. Contested ones and the raids are always listed. Also the switch beside the Journal's search."] = "列表中显示位于哪一方领地的地下城。争夺中的地下城和团队副本始终列出。也可通过手册搜索框旁的开关设置。"
L["The Edit Items window."] = "编辑物品窗口。"
L["The extra gap between your aura and Righteous Fury and the class buttons."] = "你的光环和正义之怒与职业按钮之间的额外间距。"
L["The fastest way to any waypoint."] = "前往任意路径点的最快路线。"
L["The first %d of %d; type more to narrow it down."] = "显示前%d个，共%d个；输入更多内容以缩小范围。"
L["The first time someone speaks, ask their Naowh Forever for their zone with a hidden addon whisper. Players without it never see the question."] = "某人首次发言时，通过隐藏的插件密语向其 Naowh Forever 询问所在区域。未安装的玩家不会看到该询问。"
L["The flight time to each destination when you hover it on the flight master's map."] = "在飞行管理员地图上悬停目的地时显示飞行时间。"
L["The font for damage and healing numbers, over enemies and over your character. Off leaves the game's own font alone."] = "伤害和治疗数字的字体，包括敌人头顶和你角色头顶的数字。关闭时不改动游戏自带字体。"
L["The font for the rest of the game: menus, chat, tooltips and names. Off leaves the game's own fonts alone."] = "游戏其余部分的字体：菜单、聊天、鼠标提示和名字。关闭时不改动游戏自带字体。"
L["The font for this addon's windows and HUD. Font settings on a feature use it unless they pick their own. Saved for this computer.|n|nTakes effect after a /reload."] = "本插件窗口和HUD的字体。各功能的字体设置默认使用它，除非另行选择。保存于本机。|n|n执行 /reload 后生效。"
L["The FPS / MS readout and the online counts on the buttons."] = "FPS / MS 读数和按钮上的在线人数。"
