L["The macros the addon writes and keeps up to date for you, out of combat. Switch one on here, or take it to your bars from Smart Macros in Naowh's Forge."] = "插件在非战斗时为你编写并保持更新的宏。在此开启，或从 Naowh 宏工坊的智能宏中拖到动作条上。"
