L["The map's window, the Journal beside the world map and Boss Loot at Cursor."] = "地图窗口、世界地图旁的手册以及“光标处显示首领掉落”。"
L["The marks on the game's own character panel, as it looks (or EllesmereUI's), without the Naowh Character Panel. With it on, its slots have them already."] = "在游戏自带的角色面板（或 EllesmereUI 的）上显示标记，无需 Naowh 角色面板。开启 Naowh 角色面板时，其栏位已自带标记。"
L["The Middle-click line."] = "“中键点击”提示行。"
L["The most recent completed levels."] = "最近完成的等级。"
L["the name is empty"] = "名称为空"
L["The name on it, and the community it is made for."] = "上面的名称，以及它所面向的社区。"
L["The Naowh Forever button on the minimap. The addon compartment entry and /naowh open this window either way."] = "小地图上的 Naowh Forever 按钮。无论是否显示，插件菜单条目和 /naowh 都能打开此窗口。"
L["The Naowh Forever N next to the name of Naowh, the developers, the moderators and our Legendary and Epic patrons in chat."] = "在聊天中，Naowh、开发者、管理员以及传说和史诗档位赞助者的名字旁显示 Naowh Forever 的 N 标志。"
L["The newest line stays at the anchor; older lines stack in this direction."] = "最新的一行位于锚点处；较旧的行沿此方向堆叠。"
L["The next one frees in "] = "下一个空出还需"
L["the next rank of %s (cap %d)"] = "%s的下一等级（上限%d）"
L["The number on each icon counts your bank as well as your bags."] = "每个图标上的数字同时统计银行和背包。"
L["The order the points are taken in"] = "点数的点取顺序"
L["the pattern"] = "该图样"
L["The people and projects behind Naowh Forever."] = "Naowh Forever 背后的人和项目。"
L["The picked boss's loot and abilities, under the map."] = "在地图下方显示所选首领的掉落和技能。"
L["The planner's own window, and a mini bar to leave up while you level."] = "规划器的窗口，以及可在升级时常驻的小条。"
L["The player list opens after combat."] = "玩家列表将在战斗结束后打开。"
L["The player's guild rank beside their guild name."] = "在公会名称旁显示玩家的公会会阶。"
L["The point of the bar that attaches."] = "条上用于附着的锚点。"
L["The point of the frame it attaches to."] = "所附着框体上的锚点。"
L["The purchase failed."] = "购买失败。"
L["The purchase failed; the price may have changed."] = "购买失败；价格可能已变动。"
L["The purchase failed; the price may have changed.|r"] = "购买失败；价格可能已变动。|r"
L["The quest tracker, and sharing dungeon quests with your group."] = "任务追踪，以及与队伍分享地下城任务。"
L["The quests that reward a pick you do not have yet."] = "奖励你尚未拥有的所选物品的任务。"
L["The quiz opens when you sit down at a campfire and closes when you stand up."] = "在营火旁坐下时打开问答，站起时关闭。"
L["The raid marker Mark Focus puts on your focus."] = "“标记焦点”在你焦点目标上放置的团队标记。"
L["the rank before"] = "前一等级"
L["The ready ring shows with GCD Sweep on."] = "开启公共冷却转圈时显示就绪光圈。"
L["The reagents your known spells use, such as Arcane Powder, candles, seeds, Symbols of Kings and Flash Powder, matched to the highest rank you know."] = "你已学会的法术所用的施法材料，例如魔粉、蜡烛、种子、王者印记和闪光粉，按你所知的最高等级匹配。"
L["The red time left blinks, to catch your eye."] = "红色的剩余时间会闪烁，以引起注意。"
L["The same required-level filter applies to every stack, not each item separately."] = "相同的需求等级过滤适用于每一组，而非单独针对每件物品。"
L["The same sets as the character sheet's: equip, save, rename or delete them in the Gear Sets window."] = "与角色面板中相同的方案：可在装备方案窗口中装备、保存、重命名或删除。"
L["The same with a Greater Blessing, for a class that shares one blessing, while you carry Symbols of Kings."] = "携带王者印记时，对共享同一祝福的职业改用强效祝福，效果相同。"
L["The seconds left when the time turns red; it turns yellow at twice that."] = "剩余多少秒时变为红色；在两倍于此时变为黄色。"
L["The serializer libraries are missing from this build."] = "此版本缺少序列化库。"
L["The shape of Naowh's arrow."] = "Naowh 箭头的形状。"
L["The share of what the items sell for that the suggested tip adds on top of paying back the crafter's own materials. At least 1s unless set to 0."] = "建议小费在偿还制造者自身材料之外，额外加上物品售价的这一比例。除非设为0，否则至少为1银。"
L["The shortest time between two thanks to the same player."] = "对同一玩家两次感谢之间的最短间隔。"
L["The Slot"] = "栏位"
L["The slot it is for."] = "它对应的栏位。"
L["The slots and stats only"] = "仅栏位和属性"
L["The space between Naowh's arrow and the text under it."] = "Naowh 箭头与其下方文字之间的间距。"
L["The spec your gear is weighed for. Automatic follows your talents: the tree with the most points (a druid's Feral is weighed for damage; pick Feral Tank for a bear)."] = "用于衡量装备的专精。“自动”会跟随你的天赋：取点数最多的天赋树（德鲁伊的野性按伤害衡量；熊形态请选择野性坦克）。"
L["The spot ahead of you, 312 yards away."] = "前方312码处的地点。"
L["The spot off to your right."] = "你右侧的地点。"
L["The stat weights each spec starts with."] = "每个专精的初始属性权重。"
L["The stealthed text while you are in stealth, as well as the reminder when you are not."] = "潜行时显示潜行文字，未潜行时显示提醒。"
L["The step and distance text under RestedXP's waypoint arrow."] = "RestedXP 路径点箭头下方的步骤和距离文字。"
L["The string is damaged: copy it again in full."] = "字符串已损坏：请重新完整复制。"
L["The suggested tip pays back the crafter's materials plus %d%% of what the items sell for (of all the materials, for a recipe that makes no item), rounded, at least 1s. Set a tip of your own in the order list on the right. Change the share in the Professions settings."] = "建议小费为制造者的材料费加上物品售价的%d%%（若配方不产出物品，则按全部材料计算），取整，至少1银。可在右侧订单列表中自定义小费。可在专业设置中更改比例。"
L["The swing timer needs WoW: Forever's own swing event."] = "平砍计时条需要 WoW: Forever 自带的挥击事件。"
L["The tag in the speaker's class color. Off, it is grey."] = "标签使用发言者的职业颜色。关闭时为灰色。"
L["the talent above it"] = "其上方的天赋"
L["The talent builds you saved in the Training Planner."] = "你在训练规划中保存的天赋方案。"
L["The Team"] = "团队成员"
L["The text in the theme's accent color instead of gold."] = "文字使用主题的强调色，而非金色。"
L["The theme RestedXP uses: its own, or one of the Naowh themes."] = "RestedXP 使用的主题：其自带主题或 Naowh 主题之一。"
L["The time between the two sides. Click it for the calendar (not with a gamepad)."] = "两侧之间的时间。点击打开日历（手柄不可用）。"
L["The time left turns yellow, then red near the end, so you see crowd control about to break."] = "剩余时间先变黄，临近结束时变红，让你看到控制效果即将结束。"
L["The time left, turning yellow, then red, as the camp runs down."] = "剩余时间，随营地效果即将结束依次变黄、变红。"
L["The tint on every button's icon: Naowh's own and any addon's."] = "所有按钮图标的着色：包括 Naowh 自身和其他插件的按钮。"
L["The Training Planner's help while you level: a toast when you level up with spells to train, and a panel beside your class trainer."] = "训练规划在升级时的辅助：升级后有法术可训练时弹出通知，以及职业训练师旁的面板。"
