L["The XP of quests still in progress. By default the completed quests color, faded."] = "进行中任务的经验值。默认使用已完成任务的颜色并淡化。"
L["The zone of whoever speaks in a chat channel, guild chat or a whisper, in front of their message. The game never says where a stranger is, so a player is tagged once they are in the Group Finder, your guild, your friends or your group, came up in a /who, or answered from their own copy of Naowh Forever. Their first message may come through untagged."] = "在频道聊天、公会聊天或密语中，于消息前显示发言者所在区域。游戏不会提供陌生人的位置，因此只有当玩家在寻求组队中、你的公会、好友或队伍中、出现在 /who 结果里，或由其自己的 Naowh Forever 作出回应后，才会被标注。其第一条消息可能没有标注。"
