L["Welcome, and thank you for joining us"] = "欢迎，感谢你的加入"
L["What a point of each stat is worth to your spec."] = "每点属性对你的专精价值多少。"
L["What a saved set brings back when you import it. Sets are saved and imported from the Action Bars window, out of combat."] = "导入已保存方案时会恢复哪些内容。方案在动作条窗口中保存和导入，且需在非战斗状态下进行。"
L["What a waypoint from the Discovery window or the tracker does."] = "从探索窗口或追踪器设置路径点时的行为。"
L["What a zone's page in the Quest List window lists."] = "任务列表窗口中区域页面列出的内容。"
L["What a zone's page in the Quest List window lists. Kills count from when Discovery is on: Shift-click a rare there to tick off one you killed before."] = "任务列表窗口中区域页面列出的内容。击杀数从启用探索时开始计算：在那里Shift+点击稀有怪可标记你之前击杀过的。"
L["What changed in recent builds."] = "近期版本的改动。"
L["WHAT COMES ACROSS"] = "导入内容"
L["What drops in every dungeon and raid."] = "每个地下城和团队副本的掉落。"
L["What each line is worth, in gold, silver and copper."] = "每行的价值，以金、银、铜显示。"
L["What each stack is worth, in its largest coin, under its icon."] = "每堆物品的价值，以最大面值的货币显示在图标下方。"
L["What each stat is worth to your spec: change them as you like."] = "每项属性对你专精的价值：可随意修改。"
L["What each stat is worth to your spec: the BiS List's upgrade percents and enchants come from them. Change the weights in the Stat Weights window, from the scales on the BiS List's title bar."] = "每项属性对你专精的价值：BiS列表的提升百分比和附魔都由此得出。可在属性权重窗口中修改权重，通过BiS列表标题栏上的天平图标打开。"
L["What each stat is worth to your spec: the upgrade percents and enchants come from them. Set your own."] = "每项属性对你专精的价值：提升百分比和附魔都由此得出。可自行设置。"
L["What Happened"] = "发生了什么"
L["What happens when you open a vendor. Both work whether or not the Restock Reminder is on."] = "打开商人时的行为。无论补货提醒是否开启，两者都有效。"
L["What It Lists"] = "列出内容"
L["What it lists"] = "列出内容"
L["What it puts on you: a buff, or an enchant on a weapon."] = "它为你提供什么：一个增益效果，或武器上的附魔。"
L["What it says while you are in stealth."] = "潜行状态下显示的文字。"
L["What it says while you are out of stealth."] = "非潜行状态下显示的文字。"
L["What it shows as you enter combat."] = "进入战斗时显示的内容。"
L["What it shows as you leave combat."] = "离开战斗时显示的内容。"
L["What Lines Show"] = "行显示内容"
L["What Naowh's profession window adds to each recipe: the ones you have not learned yet, your next rank, and how many of each reagent you have."] = "Naowh专业窗口为每个配方添加的内容：尚未学会的配方、你的下一个等级，以及每种材料的持有数量。"
L["What opens when a flight starts; Off hides the Games button."] = "开始飞行时打开的内容；关闭则隐藏小游戏按钮。"
L["What Rows Show"] = "行显示内容"
L["What shows while you know a find but track none."] = "你掌握寻找技能但未追踪任何内容时显示的内容。"
L["What the copy card has selected when it opens."] = "复制卡片打开时默认选中的内容。"
L["What the Journal lists on a boss. The same switches as the Filters icon on its title bar."] = "手册在首领页面上列出的内容。与其标题栏上过滤图标中的开关相同。"
L["What the stack fetches at the auction house, from your last Scan Prices or TradeSkillMaster."] = "该堆物品在拍卖行的价格，来自你上次的扫描价格或TradeSkillMaster。"
L["What the whole stack sells for at a vendor, and each item's price."] = "整堆物品卖给商人的价格，以及每件物品的价格。"
L["What to train at each level, and its cost."] = "每个等级要训练的技能及其花费。"
L["What you can train now and what each level brings."] = "现在可训练的技能，以及每个等级带来的内容。"
L["What you can train now, what each level brings and what it costs."] = "现在可训练的技能、每个等级带来的内容及其花费。"
L["What you pay the crafter for this craft, sent with the whisper. Filled in with the suggested tip; type your own as 2g 50s, 75s or 2.5 (gold). Empty it to go back to the suggestion."] = "为此次制造付给制造者的费用，随密语一同发送。默认填入建议小费；可自行输入，如2g 50s、75s或2.5（金）。清空即恢复建议值。"
L["What you wear that takes a better enchant for your level."] = "你穿戴的装备中，有适合你等级的更好附魔可用的部位。"
L["What your target is doing in a fight: their short buffs and the crowd control on them."] = "你的目标在战斗中的状态：短时增益效果和其身上的控制效果。"
L["Wheel"] = "滚轮"
L["Wheel on the rows"] = "在行上滚动滚轮"
L["Wheel: size. Right-click for more."] = "滚轮：大小。右键点击查看更多。"
L["Wheel: text size. Click a line to hide it. Right-click for more."] = "滚轮：文字大小。点击一行将其隐藏。右键点击查看更多。"
L["When"] = "时机"
L["When a profession's skill is high enough for its next rank (Journeyman, Expert, Artisan), a banner under the skill bar and on its card in the overview says what it takes and who teaches it: the nearest trainer, book vendor or quest giver. Click Waypoint to mark them on your map. Reaching it also says so once in chat; /naowh profrank repeats that."] = "当专业技能达到下一等级（熟练、专家、大师）的要求时，技能条下方和总览中的卡片上会显示横幅，说明需要什么以及由谁传授：最近的训练师、技能书商人或任务发布者。点击“路径点”可在地图上标记他们。达到时也会在聊天中提示一次；/naowh profrank 可再次显示。"
L["When an item on your list is up for a roll or in the loot window, and again when it is yours. Move the on-screen alert in the HUD Editor."] = "当你列表中的物品正在掷骰或出现在拾取窗口时提醒，归你时再次提醒。可在HUD编辑器中移动屏幕提示。"
L["When an NPC offers several things, goes straight to a finished quest to hand in, or the first quest on offer. Works with the two options above."] = "当NPC提供多个选项时，直接选择可交付的已完成任务，或第一个可接任务。可与上面两个选项配合使用。"
L["When it is up for a roll or drops."] = "正在掷骰或掉落时。"
L["When it is yours."] = "归你时。"
L["When You Leave"] = "离开时"
L["When you level up with new spells to train, a toast says how many and what they cost, with buttons to open the planner and to put a waypoint on your nearest trainer. Move it in the HUD Editor."] = "升级后有新法术可训练时，会弹出提示显示数量和花费，并提供打开规划器和为最近训练师设置路径点的按钮。可在HUD编辑器中移动。"
L["When you log out, the set this character saved last is saved again with your bars, macros and keybinds as they are."] = "登出时，此角色最后保存的方案会按你当前的动作条、宏和按键绑定重新保存。"
L["When you reach a city or inn, a flashing list in the middle of the screen of what you are short on. It stays up until you have what you need or leave. Move it in the HUD Editor."] = "到达城市或旅店时，屏幕中央会闪烁显示你缺少的物品列表。直到你备齐或离开前都会显示。可在HUD编辑器中移动。"
L["When You Reset"] = "重置时"
L["Where"] = "地点"
L["Where %s starts is not known."] = "未知%s的起始位置。"
L["Where do you want to start?"] = "你想从哪里开始？"
L["Where it comes from is not recorded yet; try the Auction House."] = "尚未记录其来源；可以试试拍卖行。"
L["Where It Drops"] = "掉落地点"
L["Where on the frame the bar sits."] = "条在框体上的位置。"
L["Where to get them"] = "获取地点"
L["Where your distance to pulling aggro and the entry count sit: under the bars, or between the title bar and the bars."] = "你距离夺取仇恨的差距和条目数的显示位置：在条下方，或在标题栏与条之间。"
L["Where your star sits: on the icon's corner, before the name, or hidden."] = "你的星标位置：图标角落、名称前或隐藏。"
L["Where? on Whispers"] = "密语中的“在哪？”"
L["Whether a healthstone or a potion comes first."] = "优先使用治疗石还是药水。"
L["Whether a new mark counts on every character or only this one."] = "新标记对所有角色生效还是仅对此角色生效。"
L["Whether NF Food leaves drinks to NF Drink."] = "NF Food是否将饮料留给NF Drink。"
L["Which blessing you give this class: Might, Wisdom, Kings, Salvation or Light."] = "你给此职业施加的祝福：力量、智慧、王者、拯救或光明。"
L["Which crowd control shows, by ability: every rank, and the same spell from items and creatures."] = "按技能显示哪些控制效果：所有等级，以及来自物品和生物的同一法术。"
L["Which debuffs show beside crowd control: off until you light them."] = "控制效果旁显示哪些减益效果：点亮前均为关闭。"
L["Which guild and title lines show with players' names, saved by the game itself."] = "玩家名称旁显示哪些公会和头衔行，由游戏本身保存。"
L["Which kinds of consumable Scan Bags adds and Ask to Add asks about."] = "“扫描背包”会添加、“询问添加”会询问的消耗品种类。"
L["Which mana spells get the line."] = "哪些法力法术显示该线。"
L["Which modules do you want?"] = "你想要哪些模块？"
L["Which of your picks alert: your BiS only, your top two, or every pick on your list."] = "你的哪些选择会提醒：仅BiS、前两名，或列表中的所有选择。"
L["Which the macro uses first when you carry both: a healthstone or a healing potion."] = "同时携带两者时宏优先使用哪一个：治疗石还是治疗药水。"
L["While a merchant is open, a Buy button under the chosen recipe's reagents buys from them, in one click, every checked reagent they sell, such as Coarse Thread or Weak Flux, for as many crafts as you set beside it. The total cost shows beside the button; hover Buy for each reagent."] = "商人窗口打开时，所选配方的材料下方会出现“购买”按钮，一键购买该商人出售的所有已勾选材料（如粗线或弱效助熔剂），数量足够你在旁边设定的制造次数。按钮旁显示总花费；鼠标悬停在“购买”上可查看每种材料。"
L["While flying"] = "飞行时"
L["While flying and at the campfire"] = "飞行时和在营火旁"
L["While Heroic Strike, Cleave, Maul or Raptor Strike is queued, the melee bars take its color and name."] = "英勇打击、顺劈斩、槌击或猛禽一击排队时，近战条会显示其颜色和名称。"
L["While the auction house is open, a Buy button under the chosen recipe's reagents buys the materials for as many crafts as you set beside it: every checked reagent that vendors do not sell. Each one shows its price first and is only bought when you click Confirm."] = "拍卖行打开时，所选配方的材料下方会出现“购买”按钮，购买足够你在旁边设定的制造次数的材料：所有商人不出售的已勾选材料。每种材料会先显示价格，只有点击“确认”后才会购买。"
L["While the auction house is open, a Search AH button next to the chosen recipe's name searches it for the item the recipe makes. Unlearned recipes also get Search Recipe, for the pattern, plans or manual that teaches it. Recipes that make no item, such as enchants, get no Search AH."] = "拍卖行打开时，所选配方名称旁会出现“搜索拍卖行”按钮，搜索该配方制造的物品。未学会的配方还会有“搜索配方”按钮，用于搜索传授它的图样、设计图或手册。不制造物品的配方（如附魔）没有“搜索拍卖行”按钮。"
L["While the auction house is open, Shift-click a recipe or a reagent to search the auction house for the item: what the recipe makes, or the reagent. While you type in chat, Shift-click still links it."] = "拍卖行打开时，Shift+点击配方或材料可在拍卖行搜索该物品：配方制造的物品或该材料。在聊天中输入时，Shift+点击仍会链接物品。"
L["While the mouse is away, with Show On Mouseover on."] = "鼠标移开时，需开启“鼠标悬停时显示”。"
L["While you are in a group, shares each quest you accept from an NPC with the others, if the quest can be shared. A quest someone shared with you is not shared again. The Modifier as you accept keeps it to yourself."] = "在队伍中时，将你从NPC处接受的每个任务共享给其他人（如果任务可共享）。别人共享给你的任务不会再次共享。接受任务时按住修饰键则不共享。"
L["While you carry books, a pin on who takes them: your librarian, or the mage trainer."] = "携带书籍时，标记收书的人：你的图书管理员或法师训练师。"
L["While you cast, mark where the cast ends on the Main Hand bar. It turns red when the cast will still be going as the swing comes due."] = "施法时，在主手条上标记施法结束的位置。如果挥击到来时施法仍未结束，标记会变红。"
L["whisper"] = "密语"
L["Whisper "] = "密语 "
L["Whisper Lines"] = "密语内容"
L["Whisper your target"] = "密语你的目标"
L["Whispers for "] = "密语："
L["Whispers thanks when a player gives you a class buff in the open world; turn friendly nameplates on so the game can name them."] = "在野外有玩家给你施加职业增益时，通过密语表示感谢；需开启友方姓名板，游戏才能识别其名字。"
L["White: exact, from their Naowh Forever. Grey: added up from their gear."] = "白色：精确值，来自其Naowh Forever。灰色：根据其装备累加。"
L["Who the cast is aimed at, in their class color."] = "施法目标，以其职业颜色显示。"
L["Whoever holds aggro in one color."] = "持有仇恨的人使用单一颜色。"
L["Whose ranking the picker shows. Each spec keeps its own picks on a list."] = "选择器显示谁的排名。每个专精在列表中保留各自的选择。"
L["Wide kite"] = "宽风筝形"
L["Widen the swing and Auto Shot windows by your world latency, so they show when to press rather than when the server acts."] = "按你的世界延迟加宽挥击和自动射击窗口，使其显示何时按键，而不是服务器何时执行。"
L["Width"] = "宽度"
L["Width and Height"] = "宽度和高度"
L["Wild Lines"] = "野性印记语句"
L["Window"] = "窗口"
L["Window Color"] = "窗口颜色"
L["Window Height"] = "窗口高度"
L["Window Length"] = "窗口时长"
L["Window Lock"] = "锁定窗口"
L["Window Opacity"] = "窗口不透明度"
