L["Your experience per hour on a small card, with time to level, played time, session length and recent level times. Hidden at max level. Hover it for Start, Pause and Reset (also /naowh xp start, pause or reset). Move it in the HUD Editor."] = "在小卡片上显示每小时经验值，以及升级所需时间、游戏时间、本次时长和近期升级用时。满级时隐藏。鼠标悬停可开始、暂停和重置（也可用/naowh xp start、pause或reset）。在HUD编辑器中移动。"
