L["Your target's buffs that last a short while, like Divine Shield, Evasion or Sprint."] = "目标持续时间较短的增益效果，如圣盾术、闪避或疾跑。"
L["Your target's short buffs and crowd control."] = "目标的短时增益和控制效果。"
L["Your target's short buffs, the crowd control on them and the debuffs you pick, as large icons that keep working in combat."] = "目标的短时增益、其身上的控制效果以及你挑选的减益效果，以大图标显示，战斗中仍可正常工作。"
