L["Your trinkets, weapons and ranged slot in a small window when you enter a dungeon or raid, or on a ready check, so a wrong trinket gets noticed before the pull. Drag the window to move it."] = "进入地下城或团队副本，或就位确认时，在小窗口中显示你的饰品、武器和远程栏位，以便开怪前发现错误的饰品。拖动窗口可移动。"
L["Your two trinket slots, movable: left-click to use one, right-click to equip a trinket from your bags outside combat. Move it in the HUD Editor."] = "你的两个饰品栏位，可移动：左键点击使用，非战斗时右键点击从背包中装备饰品。在HUD编辑器中移动。"
